-- Set statutory GST on dump-loaded products and back it out of sale_price
-- so POS still charges the same listed amount the shop bills today.
--
-- Billing (app/services/billing.py) is GST-exclusive:
--   line_total = sale_price + sale_price * gst_rate / 100
-- Legacy rows in 08_product.sql copied item_details.Cgst+Sgst (almost all 0),
-- while sale_price was the farmer-facing pack price. If we only set gst_rate,
-- a ₹50 pesticide would print as ₹59. This script keeps that bill at ₹50.
--
-- GST from product.category (already inferred from HSN + name in 08_product.sql):
--   seed         0%   (HSN 10 / 12 / 07, sowing seed)     — sale_price unchanged
--   fertilizer   5%   (HSN 31 / 28 / 25, NPK, urea, micro)
--   pesticide   18%   (HSN 38 and everything else)
-- MRP is left as listed. purchase_price is backed out in 23_product_purchase_gst.sql.
-- Historical invoice lines are not touched.
--
-- Exclusive price is chosen so billed total (half-even, 2 dp, same as the API)
-- matches today's sale_price. Amounts that cannot hit exactly at 5%/18%
-- land 1 paise under. Zero listed prices stay 0 (GST rate is still set).
--
-- Review before running. Idempotent: skips a row if sale_price moved or
-- attributes.gst_backed_out is already true.
--
--   mysql -u root -p skac_new < deploy/mysql/migrate_from_dump/22_product_gst.sql
--
-- Products in 08_product.sql: 3887
--   seed 0%:        450
--   fertilizer 5%:  1356
--   pesticide 18%:  2081
--   already had gst_rate > 0 in dump: 10 (still backed out from listed sale_price)
-- Rows updated: 3437  (seeds with 0% and unchanged price omitted)
-- Billed vs listed: exact 3522  -₹0.01 365  +₹0.01 0

USE skac_new;
SET NAMES utf8mb4;

DROP TEMPORARY TABLE IF EXISTS product_gst_fix;
CREATE TEMPORARY TABLE product_gst_fix (
  id INT PRIMARY KEY,
  old_gst DECIMAL(5,2) NOT NULL,
  new_gst DECIMAL(5,2) NOT NULL,
  old_sale DECIMAL(12,2) NOT NULL,
  new_sale DECIMAL(12,2) NOT NULL,
  billed_after DECIMAL(12,2) NOT NULL
);



















-- Review: how many SKUs move to each rate, and the exclusive vs listed totals.
SELECT f.new_gst AS gst_pct, COUNT(*) AS sku,
       SUM(f.old_sale) AS listed_sale, SUM(f.new_sale) AS exclusive_sale,
       SUM(f.billed_after) AS billed_after,
       SUM(f.billed_after) - SUM(f.old_sale) AS billed_minus_listed
FROM product_gst_fix f
GROUP BY f.new_gst
ORDER BY f.new_gst;

SELECT p.category, p.hsn_code, COUNT(*) AS sku, f.new_gst
FROM product_gst_fix f
JOIN product p ON p.id = f.id
GROUP BY p.category, p.hsn_code, f.new_gst
ORDER BY sku DESC, p.category, p.hsn_code
LIMIT 40;

SELECT p.id, p.sku, p.name, p.category, p.hsn_code,
       f.old_gst, f.new_gst, f.old_sale, f.new_sale, f.billed_after,
       f.billed_after - f.old_sale AS paise_diff
FROM product_gst_fix f
JOIN product p ON p.id = f.id
WHERE f.billed_after <> f.old_sale
ORDER BY p.category, p.name, p.id;

-- Write. Safe to re-run: only rows still sitting at the dump listed price.
UPDATE product p
JOIN product_gst_fix f ON f.id = p.id
SET
  p.gst_rate = f.new_gst,
  p.sale_price = f.new_sale,
  p.attributes = JSON_SET(
    COALESCE(p.attributes, JSON_OBJECT()),
    '$.legacy_sale_price', f.old_sale,
    '$.gst_backed_out', TRUE
  )
WHERE p.organization_id = 1
  AND p.sale_price = f.old_sale
  AND IFNULL(JSON_EXTRACT(p.attributes, '$.gst_backed_out'), FALSE) = FALSE;

SELECT ROW_COUNT() AS products_updated;

-- Spot-check: billed total vs the original listed price.
SELECT p.id, p.name, p.category, p.gst_rate, p.sale_price,
       JSON_UNQUOTE(JSON_EXTRACT(p.attributes, '$.legacy_sale_price')) AS listed_was,
       ROUND(p.sale_price + ROUND(p.sale_price * p.gst_rate / 100, 2), 2) AS mysql_round_bill
FROM product p
JOIN product_gst_fix f ON f.id = p.id
ORDER BY p.category, p.name
LIMIT 25;
